from subprocess import call
import io


class PcInterfaceManager(object):
    def turn_on_iphy(self):
        """Turns on interface for IPHY"""
        self.turn_on('eth2')

    def turn_on_enb(self):
        """Turns on interface for eNB"""
        self.turn_on('eth1')

    def turn_on_all(self):
        """Turns on all interfaces for eNB and IPHY"""
        for eth in range(1, 5):
            eth_check = 'eth{}'.format(eth)
            if not self._is_interface_on(eth_check):
                self.turn_off(eth_check)
                self.turn_on(eth_check)

    def turn_off_iphy(self):
        """Turns off interface for IPHY"""
        self.turn_off('eth2')

    def turn_off_enb(self):
        """Turns off interface for eNB"""
        self.turn_off('eth1')

    def turn_off_all(self):
        """Turns on all interfaces for eNB and IPHY"""
        for eth in range(1, 5):
            self.turn_off('eth{}'.format(eth))

    def turn_on(self, eth):
        """Turns on specified interface"""
        call('sudo ifup {}'.format(eth), shell=True)

    def turn_off(self, eth):
        """Turns off specified interface"""
        call('sudo ifdown {}'.format(eth), shell=True)

    def _is_interface_on(self, eth):
        operstate = self._check_eth_operstate(eth)
        return True if operstate == "up" else False

    def _check_eth_operstate(self, eth):
        state_path = '/sys/class/net/{}/operstate'.format(eth)
        with io.open(state_path, 'r') as statefile:
            operstate = statefile.read().rstrip()
            return operstate

    def turn_on_all_lmp(self):
        """Turns on LMP interfaces for eNB and IPHY"""
        self.turn_on_iphy()
        self.turn_on_enb()

    def turn_off_all_lmp(self):
        """Turns off LMP interfaces for eNB and IPHY"""
        self.turn_off_iphy()
        self.turn_off_enb()
